  const micro=Math.sin(sx*0.4+sy*0.3+t*4)*Math.sin(sx*0.3-sy*0.4-t*3.5)*0.08;
  const blend=reaction*0.65+cell*0.2+micro*0.15, v=blend*0.5+0.5;
  const a=v*Math.PI*2;
  const pal=(n)=>{
    const c=[
      0.5+0.5*Math.cos(n*6.283+0.0),
      0.5+0.5*Math.cos(n*6.283+1.8),
      0.5+0.5*Math.cos(n*6.283+3.6)
    ];
    return c.map((cv,i)=>{
      const ramp=Math.pow(cv,0.9+i*0.15);
      const shift=Math.sin(v*3.14159+t*0.5)*0.08;
      return Math.max(0,Math.min(1,ramp+shift));
    });
  };
  const[pR,pG,pB]=pal(v*0.8+Math.sin(t*0.3)*0.05+reaction*0.1);
