  const r=Math.min(255,((pR*lum*edge+glow*0.4)*255))|0;
  const g=Math.min(255,((pG*lum*edge+glow*0.6)*255))|0;
  const b=Math.min(255,((pB*lum*edge+glow*0.3)*255))|0;
  return[r,g,b];
}
